-- EM126 battery wagon visuals; production and energy logic are configured elsewhere.
local name="em-battery-wagon"
local p=table.deepcopy(assert(data.raw["cargo-wagon"]["cargo-wagon"]))
local root="__ElectrifiedMainline__/graphics/entity/wagon-v2/battery/"
local function layer(kind)
  local files={}
  for i=0,7 do files[#files+1]=root..string.format("%s-%02d.png",kind,i) end
  return {filenames=files,lines_per_file=4,width=512,height=512,direction_count=256,
    line_length=8,scale=0.5,shift={0,-1},apply_projection=false,back_equals_front=false,
    dice=4,priority="high",usage="train"}
end
local body,mask,shadow=layer("body"),layer("mask"),layer("shadow")
mask.flags={"mask"};mask.apply_runtime_tint=true;mask.tint_as_overlay=false
shadow.flags={"shadow"};shadow.draw_as_shadow=true
p.name=name;p.localised_name={"entity-name."..name}
p.inventory_size=0;p.quality_affects_inventory_size=false
p.pictures={rotated={layers={body,mask,shadow}}}
p.color={r=0.92,g=0.07,b=0,a=1}
p.wheels=table.deepcopy(assert(data.raw.locomotive["em-electric-locomotive"].wheels))
p.horizontal_doors=nil;p.vertical_doors=nil;p.next_upgrade=nil;p.fast_replaceable_group=nil
p.minable={mining_time=0.5,result=name};p.placeable_by={item=name,count=1}
p.icon=root.."icon.png";p.icon_size=64;p.icons=nil
p.hidden=true;p.hidden_in_factoriopedia=true
p.factoriopedia_simulation=nil
local item=table.deepcopy(assert(data.raw["item-with-entity-data"]["cargo-wagon"]))
item.name=name;item.place_result=name;item.icon=p.icon;item.icon_size=64;item.icons=nil
item.hidden=true;item.hidden_in_factoriopedia=true
item.localised_name={"item-name."..name}
data:extend({p,item})
log("[EM126] native battery wagon, calibrated body and runtime stripe mask")


